from __future__ import annotations

import json
import os
import time
import uuid
from typing import Any

import httpx

OPENAI_BASE_URL = "https://api.openai.com/v1"
DEFAULT_OPENAI_ORACLE_MODEL = "gpt-5.5"
OPENAI_CHAT_COMPLETIONS_BATCH_ENDPOINT = "/v1/chat/completions"
OPENAI_BATCH_FILENAME_PREFIX = "freesolo-oracle-batch"
OPENAI_REQUEST_TIMEOUT_SECONDS = 60.0

ALLOWED_OPENAI_ORACLE_MODELS = (
    DEFAULT_OPENAI_ORACLE_MODEL,
    f"openai/{DEFAULT_OPENAI_ORACLE_MODEL}",
)


def resolve_openai_model(model: str | None = None) -> str:
    if model is None or not model.strip():
        return DEFAULT_OPENAI_ORACLE_MODEL
    resolved = model.strip()
    if resolved.startswith("openai/"):
        resolved = resolved.removeprefix("openai/")
    if resolved != DEFAULT_OPENAI_ORACLE_MODEL:
        allowed = ", ".join(ALLOWED_OPENAI_ORACLE_MODELS)
        raise ValueError(f"Oracle model must be one of: {allowed}; got {model!r}")
    return resolved


def require_openai_api_key(api_key: str | None = None) -> str:
    resolved = api_key or os.getenv("OPENAI_API_KEY")
    if not resolved or not resolved.strip():
        raise RuntimeError("OPENAI_API_KEY is required")
    return resolved.strip()


def openai_headers(*, api_key: str | None = None) -> dict[str, str]:
    return {
        **openai_auth_headers(api_key=api_key),
        "Content-Type": "application/json",
    }


def openai_auth_headers(*, api_key: str | None = None) -> dict[str, str]:
    return {
        "Authorization": f"Bearer {require_openai_api_key(api_key)}",
    }


def openai_chat_completion(
    *,
    model: str,
    messages: list[dict[str, str]],
    max_tokens: int,
    api_key: str | None = None,
    base_url: str = OPENAI_BASE_URL,
    timeout_seconds: float = 60.0,
    response_format: dict[str, Any] | None = None,
    extra_body: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = build_openai_chat_payload(
        model=resolve_openai_model(model),
        messages=messages,
        max_tokens=max_tokens,
        response_format=response_format,
        extra_body=extra_body,
    )
    with httpx.Client(timeout=timeout_seconds) as client:
        response = client.post(
            f"{base_url.rstrip('/')}/chat/completions",
            headers=openai_headers(api_key=api_key),
            json=payload,
        )
        response.raise_for_status()
        data = response.json()
    if not isinstance(data, dict):
        raise RuntimeError("OpenAI response must be a JSON object")
    return data


def generate_openai_text(
    *,
    model: str,
    messages: list[dict[str, str]],
    max_tokens: int,
    api_key: str | None = None,
    base_url: str = OPENAI_BASE_URL,
    timeout_seconds: float = 60.0,
    response_format: dict[str, Any] | None = None,
    extra_body: dict[str, Any] | None = None,
) -> str:
    response = openai_chat_completion(
        model=model,
        messages=messages,
        max_tokens=max_tokens,
        api_key=api_key,
        base_url=base_url,
        timeout_seconds=timeout_seconds,
        response_format=response_format,
        extra_body=extra_body,
    )
    return extract_openai_message_content(response)


def build_openai_chat_payload(
    *,
    model: str,
    messages: list[dict[str, str]],
    max_tokens: int,
    response_format: dict[str, Any] | None = None,
    extra_body: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "model": model,
        "messages": messages,
        "max_completion_tokens": require_positive_max_tokens(max_tokens),
    }
    if response_format is not None:
        payload["response_format"] = response_format
    if extra_body:
        payload.update(extra_body)
    return payload


def upload_openai_batch_file(
    *,
    jsonl_text: str,
) -> dict[str, Any]:
    with httpx.Client(timeout=OPENAI_REQUEST_TIMEOUT_SECONDS) as client:
        response = client.post(
            _openai_url("/files"),
            headers=openai_auth_headers(),
            data={"purpose": "batch"},
            files={
                "file": (
                    _openai_batch_filename(),
                    jsonl_text.encode("utf-8"),
                    "application/jsonl",
                )
            },
        )
        response.raise_for_status()
        data = response.json()
    if not isinstance(data, dict):
        raise RuntimeError("OpenAI file upload response must be a JSON object")
    if not isinstance(data.get("id"), str) or not data["id"]:
        raise RuntimeError("OpenAI file upload response did not include an id")
    return data


def create_openai_batch(
    *,
    input_file_id: str,
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "input_file_id": input_file_id,
        "endpoint": OPENAI_CHAT_COMPLETIONS_BATCH_ENDPOINT,
        "completion_window": "24h",
    }
    with httpx.Client(timeout=OPENAI_REQUEST_TIMEOUT_SECONDS) as client:
        response = client.post(
            _openai_url("/batches"),
            headers=openai_headers(),
            json=payload,
        )
        response.raise_for_status()
        data = response.json()
    if not isinstance(data, dict):
        raise RuntimeError("OpenAI batch creation response must be a JSON object")
    if not isinstance(data.get("id"), str) or not data["id"]:
        raise RuntimeError("OpenAI batch creation response did not include an id")
    return data


def retrieve_openai_batch(
    batch_id: str,
) -> dict[str, Any]:
    with httpx.Client(timeout=OPENAI_REQUEST_TIMEOUT_SECONDS) as client:
        response = client.get(
            _openai_url(f"/batches/{batch_id}"),
            headers=openai_headers(),
        )
        response.raise_for_status()
        data = response.json()
    if not isinstance(data, dict):
        raise RuntimeError("OpenAI batch retrieve response must be a JSON object")
    return data


def wait_for_openai_batch(
    batch_id: str,
    *,
    poll_interval_seconds: float = 30.0,
    timeout_seconds: float = 24 * 60 * 60,
) -> dict[str, Any]:
    started = time.monotonic()
    while True:
        batch = retrieve_openai_batch(batch_id)
        status = str(batch.get("status") or "")
        if status == "completed":
            return batch
        if status in {"failed", "expired", "cancelled"}:
            raise RuntimeError(
                f"OpenAI batch {batch_id} ended with status {status}: {batch}"
            )
        if time.monotonic() - started >= timeout_seconds:
            raise TimeoutError(
                f"OpenAI batch {batch_id} did not complete within timeout"
            )
        time.sleep(max(0.0, poll_interval_seconds))


def download_openai_file_text(
    file_id: str,
) -> str:
    with httpx.Client(timeout=OPENAI_REQUEST_TIMEOUT_SECONDS) as client:
        response = client.get(
            _openai_url(f"/files/{file_id}/content"),
            headers=openai_auth_headers(),
        )
        response.raise_for_status()
        return response.text


def _openai_url(path: str) -> str:
    return f"{OPENAI_BASE_URL.rstrip('/')}/{path.lstrip('/')}"


def _openai_batch_filename() -> str:
    return f"{OPENAI_BATCH_FILENAME_PREFIX}-{uuid.uuid4().hex}.jsonl"


def iter_jsonl_objects(text: str) -> list[dict[str, Any]]:
    objects: list[dict[str, Any]] = []
    for line_number, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped:
            continue
        parsed = json.loads(stripped)
        if not isinstance(parsed, dict):
            raise RuntimeError(
                f"OpenAI batch output line {line_number} was not an object"
            )
        objects.append(parsed)
    return objects


def require_positive_max_tokens(value: Any) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError) as error:
        raise ValueError("max_tokens must be set explicitly") from error
    if parsed < 1:
        raise ValueError("max_tokens must be at least 1")
    return parsed


def extract_openai_message_content(payload: dict[str, Any]) -> str:
    choices = payload.get("choices")
    if not isinstance(choices, list) or not choices:
        raise RuntimeError("OpenAI response did not contain choices")
    first_choice = choices[0]
    message = first_choice.get("message") if isinstance(first_choice, dict) else None
    content = message.get("content") if isinstance(message, dict) else None
    if not isinstance(content, str) or not content.strip():
        raise RuntimeError("OpenAI response did not contain content")
    return content.strip()
